# Terraform Refactor: Dev/Prod Duplication → for_each Module

## Strategy

Consolidate duplicated resource blocks into a single parameterized module, then instantiate via `for_each`. The zero-diff migration uses `terraform state mv` to redirect existing state entries without triggering destroy/recreate.

---

## Phase 1: Create the Module

**`modules/app-environment/main.tf`**
```hcl
# EKS Cluster
resource "aws_eks_cluster" "cluster" {
  name            = var.cluster_name
  role_arn        = aws_iam_role.cluster.arn
  version         = var.kubernetes_version

  vpc_config {
    subnet_ids              = var.subnet_ids
    endpoint_private_access = true
    endpoint_public_access  = var.eks_public_access
  }

  depends_on = [aws_iam_role_policy_attachment.cluster_policy]
}

resource "aws_eks_node_group" "workers" {
  cluster_name    = aws_eks_cluster.cluster.name
  node_group_name = "${var.environment}-nodes"
  node_role_arn   = aws_iam_role.nodes.arn
  subnet_ids      = var.subnet_ids
  version         = var.kubernetes_version

  scaling_config {
    desired_size = var.node_desired_size
    min_size     = var.node_min_size
    max_size     = var.node_max_size
  }

  instance_types = var.node_instance_types

  depends_on = [aws_iam_role_policy_attachment.nodes_policy]

  tags = var.tags
}

# S3 Bucket
resource "aws_s3_bucket" "assets" {
  bucket = var.s3_bucket_name
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count = var.enable_s3_replication ? 1 : 0

  bucket = aws_s3_bucket.assets.id

  role = aws_iam_role.s3_replication[0].arn

  rule {
    status   = "Enabled"
    priority = 1

    filter {
      prefix = ""
    }

    destination {
      bucket       = var.s3_replica_bucket_arn
      storage_class = "STANDARD_IA"

      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.assets]
}

# RDS PostgreSQL
resource "aws_db_instance" "postgres" {
  identifier            = var.rds_identifier
  engine                = "postgres"
  engine_version        = var.postgres_version
  instance_class        = var.rds_instance_class
  allocated_storage     = var.allocated_storage
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_name  = "appdb"
  username = "pgadmin"
  password = random_password.db_password.result

  multi_az               = var.multi_az
  publicly_accessible    = false
  skip_final_snapshot    = false
  final_snapshot_identifier = "${var.rds_identifier}-final-snapshot-${formatdate("YYYY-MM-DD-hhmm", timestamp())}"

  backup_retention_period = var.backup_retention_days
  backup_window           = "03:00-04:00"
  maintenance_window      = "mon:04:00-mon:05:00"

  deletion_protection = var.deletion_protection

  db_subnet_group_name   = aws_db_subnet_group.postgres.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  tags = var.tags
}

resource "aws_db_subnet_group" "postgres" {
  name           = "${var.environment}-postgres-subnet-group"
  subnet_ids     = var.db_subnet_ids
  tags           = var.tags
}

resource "aws_security_group" "rds" {
  name        = "${var.environment}-rds-sg"
  description = "Security group for RDS database"
  vpc_id      = var.vpc_id

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.app.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = var.tags
}

resource "aws_security_group" "app" {
  name        = "${var.environment}-app-sg"
  description = "Security group for application"
  vpc_id      = var.vpc_id

  tags = var.tags
}

# RDS KMS Key
resource "aws_kms_key" "rds" {
  description             = "${var.environment} RDS encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${var.environment}-rds"
  target_key_id = aws_kms_key.rds.key_id
}

# Secrets Manager - DB Connection String
resource "random_password" "db_password" {
  length  = 32
  special = true
}

resource "aws_secretsmanager_secret" "db_connection" {
  name_prefix             = "${var.environment}-db-connection-"
  recovery_window_in_days = 0

  tags = var.tags
}

resource "aws_secretsmanager_secret_version" "db_connection" {
  secret_id = aws_secretsmanager_secret.db_connection.id
  secret_string = jsonencode({
    username = aws_db_instance.postgres.username
    password = random_password.db_password.result
    engine   = "postgres"
    host     = aws_db_instance.postgres.endpoint
    port     = 5432
    dbname   = aws_db_instance.postgres.db_name
  })
}

# IAM Service Account Role
resource "aws_iam_role" "service_account" {
  name_prefix = "${var.environment}-app-"
  assume_role_policy = var.environment == "prod" ? data.aws_iam_policy_document.oidc_assume.json : data.aws_iam_policy_document.basic_assume.json
}

resource "aws_iam_role_policy" "service_account" {
  name_prefix = "${var.environment}-app-policy-"
  role        = aws_iam_role.service_account.id
  policy      = data.aws_iam_policy_document.service_account.json
}

data "aws_iam_policy_document" "basic_assume" {
  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.nodes.arn]
    }
    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "oidc_assume" {
  statement {
    effect = "Allow"
    principals {
      type        = "Federated"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/${replace(aws_eks_cluster.cluster.identity[0].oidc[0].issuer, "https://", "")}"]
    }
    actions = ["sts:AssumeRoleWithWebIdentity"]
    condition {
      test     = "StringEquals"
      variable = "${replace(aws_eks_cluster.cluster.identity[0].oidc[0].issuer, "https://", "")}:sub"
      values   = ["system:serviceaccount:default:app"]
    }
  }
}

data "aws_iam_policy_document" "service_account" {
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.assets.arn,
      "${aws_s3_bucket.assets.arn}/*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue"
    ]
    resources = [aws_secretsmanager_secret.db_connection.arn]
  }

  # Prod-only: explicit least-privilege policy
  dynamic "statement" {
    for_each = var.environment == "prod" ? [1] : []
    content {
      effect = "Allow"
      actions = [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ]
      resources = ["arn:aws:logs:${var.aws_region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/eks/${var.cluster_name}/*"]
    }
  }
}

# ALB (internal for dev, can use CloudFront for prod)
resource "aws_lb" "app" {
  count           = var.create_alb ? 1 : 0
  name_prefix     = substr(var.environment, 0, 6)
  internal        = var.environment == "dev" ? true : false
  load_balancer_type = "application"
  subnets         = var.subnet_ids
  security_groups = [aws_security_group.alb[0].id]

  tags = var.tags
}

resource "aws_security_group" "alb" {
  count       = var.create_alb ? 1 : 0
  name_prefix = "${var.environment}-alb-"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = var.environment == "dev" ? var.internal_cidr_blocks : ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = var.tags
}

resource "aws_lb_listener" "https" {
  count             = var.create_alb ? 1 : 0
  load_balancer_arn = aws_lb.app[0].arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS-1-2-2017-01"
  certificate_arn   = var.certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app[0].arn
  }
}

resource "aws_lb_target_group" "app" {
  count       = var.create_alb ? 1 : 0
  name_prefix = substr(var.environment, 0, 6)
  port        = 80
  protocol    = "HTTP"
  vpc_id      = var.vpc_id

  health_check {
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
    path                = "/"
    matcher             = "200"
  }

  tags = var.tags
}

# CloudFront (prod only)
resource "aws_cloudfront_distribution" "prod" {
  count = var.environment == "prod" ? 1 : 0

  origin {
    domain_name = aws_s3_bucket.assets.bucket_regional_domain_name
    origin_id   = "S3"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.prod[0].cloudfront_access_identity_path
    }
  }

  enabled = true

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3"

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  viewer_certificate {
    acm_certificate_arn      = var.cloudfront_certificate_arn
    ssl_support_method       = "sni-only"
    minimum_protocol_version = "TLSv1.2_2021"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  tags = var.tags
}

resource "aws_cloudfront_origin_access_identity" "prod" {
  count   = var.environment == "prod" ? 1 : 0
  comment = "${var.environment} OAI"
}

resource "aws_s3_bucket_policy" "prod_cloudfront" {
  count  = var.environment == "prod" ? 1 : 0
  bucket = aws_s3_bucket.assets.id
  policy = data.aws_iam_policy_document.prod_cloudfront[0].json
}

data "aws_iam_policy_document" "prod_cloudfront" {
  count = var.environment == "prod" ? 1 : 0

  statement {
    principals {
      type        = "AWS"
      identifiers = [aws_cloudfront_origin_access_identity.prod[0].iam_arn]
    }
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }
}

# IAM Cluster & Node Role Policies
resource "aws_iam_role" "cluster" {
  name_prefix = "${var.environment}-eks-cluster-"
  assume_role_policy = data.aws_iam_policy_document.cluster_assume.json
}

data "aws_iam_policy_document" "cluster_assume" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role_policy_attachment" "cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.cluster.name
}

resource "aws_iam_role" "nodes" {
  name_prefix = "${var.environment}-eks-nodes-"
  assume_role_policy = data.aws_iam_policy_document.nodes_assume.json
}

data "aws_iam_policy_document" "nodes_assume" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role_policy_attachment" "nodes_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.nodes.name
}

resource "aws_iam_role_policy_attachment" "nodes_cni_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.nodes.name
}

resource "aws_iam_role" "s3_replication" {
  count           = var.enable_s3_replication ? 1 : 0
  name_prefix     = "${var.environment}-s3-replication-"
  assume_role_policy = data.aws_iam_policy_document.s3_replication_assume[0].json
}

data "aws_iam_policy_document" "s3_replication_assume" {
  count = var.enable_s3_replication ? 1 : 0

  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role_policy" "s3_replication" {
  count       = var.enable_s3_replication ? 1 : 0
  name_prefix = "${var.environment}-s3-replication-policy-"
  role        = aws_iam_role.s3_replication[0].id
  policy      = data.aws_iam_policy_document.s3_replication_policy[0].json
}

data "aws_iam_policy_document" "s3_replication_policy" {
  count = var.enable_s3_replication ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]
    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl"
    ]
    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete"
    ]
    resources = ["${var.s3_replica_bucket_arn}/*"]
  }
}

data "aws_caller_identity" "current" {}
```

**`modules/app-environment/variables.tf`**
```hcl
variable "environment" {
  description = "Environment name (dev or prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be dev or prod."
  }
}

variable "cluster_name" {
  description = "EKS cluster name"
  type        = string
}

variable "kubernetes_version" {
  description = "Kubernetes version"
  type        = string
  default     = "1.28"
}

variable "eks_public_access" {
  description = "Enable public access to EKS endpoint"
  type        = bool
  default     = false
}

variable "node_desired_size" {
  description = "Desired number of worker nodes"
  type        = number
}

variable "node_min_size" {
  description = "Minimum number of worker nodes"
  type        = number
  default     = 1
}

variable "node_max_size" {
  description = "Maximum number of worker nodes"
  type        = number
}

variable "node_instance_types" {
  description = "EC2 instance types for worker nodes"
  type        = list(string)
}

variable "subnet_ids" {
  description = "Subnet IDs for cluster and ALB"
  type        = list(string)
}

variable "vpc_id" {
  description = "VPC ID"
  type        = string
}

variable "db_subnet_ids" {
  description = "Subnet IDs for RDS (must span 2+ AZs for multi-AZ)"
  type        = list(string)
}

variable "s3_bucket_name" {
  description = "S3 bucket name for application assets"
  type        = string
}

variable "rds_identifier" {
  description = "RDS instance identifier"
  type        = string
}

variable "rds_instance_class" {
  description = "RDS instance class"
  type        = string
}

variable "postgres_version" {
  description = "PostgreSQL engine version"
  type        = string
  default     = "15.3"
}

variable "allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "multi_az" {
  description = "Enable multi-AZ deployment"
  type        = bool
  default     = false
}

variable "backup_retention_days" {
  description = "RDS backup retention in days"
  type        = number
  default     = 7
}

variable "deletion_protection" {
  description = "Enable deletion protection on RDS"
  type        = bool
  default     = true
}

variable "enable_s3_replication" {
  description = "Enable S3 cross-region replication"
  type        = bool
  default     = false
}

variable "s3_replica_bucket_arn" {
  description = "ARN of replica S3 bucket (required if enable_s3_replication = true)"
  type        = string
  default     = ""
}

variable "create_alb" {
  description = "Create ALB (false for prod using CloudFront only)"
  type        = bool
  default     = true
}

variable "certificate_arn" {
  description = "ACM certificate ARN for ALB listener"
  type        = string
  default     = ""
}

variable "cloudfront_certificate_arn" {
  description = "ACM certificate ARN for CloudFront (prod only)"
  type        = string
  default     = ""
}

variable "aws_region" {
  description = "AWS region"
  type        = string
}

variable "internal_cidr_blocks" {
  description = "CIDR blocks allowed to access internal ALB (dev only)"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Common tags for all resources"
  type        = map(string)
  default     = {}
}
```

**`modules/app-environment/outputs.tf`**
```hcl
output "cluster_endpoint" {
  description = "EKS cluster endpoint"
  value       = aws_eks_cluster.cluster.endpoint
}

output "cluster_name" {
  description = "EKS cluster name"
  value       = aws_eks_cluster.cluster.name
}

output "cluster_ca_certificate" {
  description = "EKS cluster CA certificate (base64)"
  value       = aws_eks_cluster.cluster.certificate_authority[0].data
  sensitive   = true
}

output "oidc_provider_arn" {
  description = "OIDC provider ARN (prod)"
  value       = var.environment == "prod" ? aws_eks_cluster.cluster.identity[0].oidc[0].issuer : null
}

output "s3_bucket_id" {
  description = "S3 bucket ID"
  value       = aws_s3_bucket.assets.id
}

output "rds_endpoint" {
  description = "RDS instance endpoint"
  value       = aws_db_instance.postgres.endpoint
}

output "rds_identifier" {
  description = "RDS instance identifier"
  value       = aws_db_instance.postgres.identifier
}

output "secret_arn" {
  description = "Secrets Manager secret ARN"
  value       = aws_secretsmanager_secret.db_connection.arn
}

output "service_account_role_arn" {
  description = "IAM role ARN for service account"
  value       = aws_iam_role.service_account.arn
}

output "alb_dns_name" {
  description = "ALB DNS name"
  value       = var.create_alb ? aws_lb.app[0].dns_name : null
}

output "cloudfront_domain_name" {
  description = "CloudFront domain name (prod only)"
  value       = var.environment == "prod" ? aws_cloudfront_distribution.prod[0].domain_name : null
}
```

---

## Phase 2: Refactored Root Module

**`main.tf`** (root)
```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

module "environments" {
  for_each = var.environments

  source = "./modules/app-environment"

  environment                = each.key
  cluster_name              = each.value.cluster_name
  node_desired_size         = each.value.node_desired_size
  node_max_size             = each.value.node_max_size
  node_instance_types       = each.value.node_instance_types
  subnet_ids                = each.value.subnet_ids
  vpc_id                    = each.value.vpc_id
  db_subnet_ids             = each.value.db_subnet_ids
  s3_bucket_name            = each.value.s3_bucket_name
  rds_identifier            = each.value.rds_identifier
  rds_instance_class        = each.value.rds_instance_class
  multi_az                  = each.value.multi_az
  backup_retention_days     = each.value.backup_retention_days
  enable_s3_replication     = each.value.enable_s3_replication
  s3_replica_bucket_arn     = each.value.s3_replica_bucket_arn
  create_alb                = each.value.create_alb
  certificate_arn           = try(each.value.certificate_arn, "")
  cloudfront_certificate_arn = try(each.value.cloudfront_certificate_arn, "")
  aws_region                = var.aws_region
  internal_cidr_blocks      = try(each.value.internal_cidr_blocks, [])

  tags = merge(
    var.common_tags,
    {
      Environment = each.key
    }
  )
}
```

**`variables.tf`** (root)
```hcl
variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "environments" {
  description = "Environment configurations"
  type = map(object({
    cluster_name              = string
    node_desired_size         = number
    node_max_size             = number
    node_instance_types       = list(string)
    subnet_ids                = list(string)
    vpc_id                    = string
    db_subnet_ids             = list(string)
    s3_bucket_name            = string
    rds_identifier            = string
    rds_instance_class        = string
    multi_az                  = bool
    backup_retention_days     = number
    enable_s3_replication     = bool
    s3_replica_bucket_arn     = string
    create_alb                = bool
    certificate_arn           = optional(string)
    cloudfront_certificate_arn = optional(string)
    internal_cidr_blocks      = optional(list(string))
  }))
}

variable "common_tags" {
  description = "Common tags for all resources"
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
    Project   = "App"
  }
}
```

**`environments/dev.tfvars`**
```hcl
aws_region = "us-east-1"

environments = {
  dev = {
    cluster_name          = "app-dev"
    node_desired_size     = 2
    node_max_size         = 3
    node_instance_types   = ["t3.medium"]
    subnet_ids            = ["subnet-dev-1a", "subnet-dev-1b", "subnet-dev-1c"]
    vpc_id                = "vpc-dev-id"
    db_subnet_ids         = ["subnet-dev-1a", "subnet-dev-1b"]
    s3_bucket_name        = "app-assets-dev-123456"
    rds_identifier        = "app-postgres-dev"
    rds_instance_class    = "db.t3.micro"
    multi_az              = false
    backup_retention_days = 7
    enable_s3_replication = false
    s3_replica_bucket_arn = ""
    create_alb            = true
    certificate_arn       = "arn:aws:acm:us-east-1:ACCOUNT:certificate/DEV-CERT"
