## Phase 3: Zero-Diff State Migration

**Migration Script: `migrate-state.sh`**
```bash
#!/bin/bash
set -e

ENVIRONMENTS=("dev" "prod")
RESOURCE_TYPES=(
  "aws_eks_cluster.cluster"
  "aws_eks_node_group.workers"
  "aws_s3_bucket.assets"
  "aws_s3_bucket_versioning.assets"
  "aws_s3_bucket_server_side_encryption_configuration.assets"
  "aws_s3_bucket_public_access_block.assets"
  "aws_s3_bucket_replication_configuration.assets"
  "aws_db_instance.postgres"
  "aws_db_subnet_group.postgres"
  "aws_security_group.rds"
  "aws_security_group.app"
  "aws_kms_key.rds"
  "aws_kms_alias.rds"
  "aws_secretsmanager_secret.db_connection"
  "aws_secretsmanager_secret_version.db_connection"
  "aws_iam_role.service_account"
  "aws_iam_role_policy.service_account"
  "aws_iam_role.cluster"
  "aws_iam_role_policy_attachment.cluster_policy"
  "aws_iam_role.nodes"
  "aws_iam_role_policy_attachment.nodes_policy"
  "aws_iam_role_policy_attachment.nodes_cni_policy"
  "aws_lb.app"
  "aws_security_group.alb"
  "aws_lb_listener.https"
  "aws_lb_target_group.app"
  "aws_cloudfront_distribution.prod"
  "aws_cloudfront_origin_access_identity.prod"
  "aws_s3_bucket_policy.prod_cloudfront"
)

echo "Starting zero-diff state migration..."
echo "This will move resources from old state keys to new module-based keys."
echo ""

for env in "${ENVIRONMENTS[@]}"; do
  echo "Processing environment: $env"

  for resource in "${RESOURCE_TYPES[@]}"; do
    old_key="${resource/_[a-z]*/.${env}}"
    new_key="module.environments[\"${env}\"].${resource}"

    # Check if old state key exists
    if terraform state show "${old_key}" &>/dev/null; then
      echo "  Moving: ${old_key} → ${new_key}"
      terraform state mv "${old_key}" "${new_key}" || echo "    (already migrated or not found)"
    fi
  done

  echo "  ✓ ${env} complete"
  echo ""
done

echo "State migration complete. Running 'terraform plan' to verify zero-diff..."
terraform plan -var-file="environments/dev.tfvars" -var-file="environments/prod.tfvars" -out=tfplan

if grep -q "Plan: 0 to add, 0 to change, 0 to destroy" tfplan; then
  echo "✓ Zero-diff verified. No resources will be modified."
  rm tfplan
  exit 0
else
  echo "✗ Plan shows changes. Review and manually investigate."
  exit 1
fi
```

